(()=>{
'use strict';

// Correct the labels generated by the report engine without changing its calculations.
function fixPlayerReportMetricLabels(){
  const summary=document.getElementById('summary');
  if(!summary)return;
  const cards=[...summary.querySelectorAll('.summary-card')];
  const winRateCard=cards.find(card=>card.firstChild?.textContent?.trim()==='Win rate');
  if(winRateCard){
    const note=winRateCard.querySelector('small');
    if(note)note.textContent='wins ÷ all games';
  }
}

const target=document.getElementById('summary');
if(target)new MutationObserver(fixPlayerReportMetricLabels).observe(target,{childList:true,subtree:true});
fixPlayerReportMetricLabels();
})();
